type Settings = { duration: number; questions: number; difficulty: Difficulty }
type FeedbackState = { correct: boolean; answer: number; answerText?: string }

function answerItems(records: AnswerRecord[]): RawItem[] { return records.map(record => ({ payload: record, responseTimeMs: record.responseTimeMs, outcome: record.correct ? 'correct' : 'incorrect' })) }
async function persist(draft: SessionDraft | null, items: RawItem[], options: Parameters<typeof completeSession>[2], reveal: () => void) {
  try { if (draft) await completeSession(draft, items, options) }
  catch { window.dispatchEvent(new CustomEvent('performance-storage-error')) }
  finally { reveal() }
}
function StorageNotice() {
  const [visible, setVisible] = useState(false)
  useEffect(() => { const show = () => setVisible(true); window.addEventListener('performance-storage-error', show); return () => window.removeEventListener('performance-storage-error', show) }, [])
  return visible ? <div className="storage-notice" role="status">Session complete, but local statistics could not be saved.<button onClick={() => setVisible(false)} aria-label="Dismiss">×</button></div> : null
}
function Layout() {
  return <><header className="site-header"><NavLink className="brand" to="/">QuantaPit</NavLink><nav aria-label="Main navigation">{navItems.map(([label, path]) => <NavLink key={path} to={path} className={({ isActive }) => isActive ? 'nav-link active' : 'nav-link'}>{label}</NavLink>)}</nav></header><main><Outlet /></main><StorageNotice /></>
}

