type VenueRoundRecord = { action: VenueGapAction; round: VenueGapRound; trade: VenueGapTrade | null; bestOpportunity: ReturnType<typeof findBestOpportunity>; budgetBefore: number; budget: number; opportunity: boolean; responseTimeMs: number }
function VenueGapSetup({ difficulty, onDifficulty, onStart }: { difficulty: VenueGapDifficulty; onDifficulty: (value: VenueGapDifficulty) => void; onStart: () => void }) { return <section className="page setup-page"><p className="eyebrow">MARKET GAMES / VENUE GAP</p><div className="game-heading"><span className="large-game-icon">⇄</span><div><h1>Venue Gap</h1><p className="section-intro">Find the same asset priced differently, then capture the spread after fees.</p></div></div><div className="setting hidden-difficulty"><label htmlFor="venue-gap-difficulty">Difficulty</label><select id="venue-gap-difficulty" value={difficulty} onChange={event => onDifficulty(event.target.value as VenueGapDifficulty)}><option>Easy</option><option>Medium</option><option>Hard</option></select></div><p className="hidden-rules">5 rounds · 2/3/4 venues · 10,000 starting budget · 60 seconds per round</p><button className="start-button" onClick={onStart}>Start market <span>→</span></button></section> }
function VenueGapResults({ records, budget, onAgain, onBack }: { records: VenueRoundRecord[]; budget: number; onAgain: () => void; onBack: () => void }) { const correct = records.filter(record => record.opportunity ? Boolean(record.trade && record.trade.netProfit > 0) : record.action !== 'arbitrage').length; const missed = records.filter(record => record.opportunity && record.action !== 'arbitrage').length; const avoid = records.filter(record => !record.opportunity && record.action === 'arbitrage').length; return <section className="page hidden-results"><p className="eyebrow">VENUE GAP / COMPLETE</p><h1>Market closed.</h1><div className="venue-gap-metrics"><div><span>Final budget</span><strong>{budget.toFixed(2)}</strong></div><div><span>P&amp;L</span><strong>{(budget - VENUE_GAP_STARTING_BUDGET).toFixed(2)}</strong></div><div><span>Correct decisions</span><strong>{correct}/{records.length}</strong></div><div><span>Opportunities missed</span><strong>{missed}</strong></div><div><span>Trades to avoid</span><strong>{avoid}</strong></div></div><div className="venue-gap-results-list">{records.map((record, index) => <div key={index}><strong>Round {index + 1} · {record.action === 'arbitrage' ? 'Trade' : record.action === 'timeout' ? 'Timeout' : 'Skipped'}</strong><span>{record.trade ? `${record.trade.quantity} units · fees ${(record.trade.buyFee + record.trade.sellFee).toFixed(2)} · P/L ${record.trade.netProfit.toFixed(2)}` : record.opportunity ? 'Opportunity missed' : 'No profitable opportunity'} · budget {record.budget.toFixed(2)}</span></div>)}</div><div className="actions"><button onClick={onAgain}>Play again</button><button className="secondary" onClick={onBack}>Back to market games</button></div></section> }
function VenueGap() {
  const [difficulty, setDifficulty] = useState<VenueGapDifficulty>('Easy'); const [status, setStatus] = useState<'setup' | 'playing' | 'reveal' | 'results'>('setup'); const [index, setIndex] = useState(0); const [round, setRound] = useState<VenueGapRound | null>(null); const [buyId, setBuyId] = useState(''); const [sellId, setSellId] = useState(''); const [quantity, setQuantity] = useState('1'); const [budget, setBudget] = useState(VENUE_GAP_STARTING_BUDGET); const [remaining, setRemaining] = useState(0); const [records, setRecords] = useState<VenueRoundRecord[]>([]); const [trade, setTrade] = useState<VenueGapTrade | null>(null); const [action, setAction] = useState<VenueGapAction | null>(null); const [error, setError] = useState(''); const resolved = useRef(false); const advanceTimer = useRef<number | null>(null); const performanceDraft = useRef<SessionDraft | null>(null); const roundStartedAt = useRef(0); const navigate = useNavigate(); const venues = round?.venues ?? []; const buy = venues.find(venue => venue.venueId === buyId) ?? null; const sell = venues.find(venue => venue.venueId === sellId) ?? null; const best = round ? findBestOpportunity(round.venues) : null
  useEffect(() => () => { if (advanceTimer.current) window.clearTimeout(advanceTimer.current) }, [])
  useEffect(() => { if (status !== 'playing') return; const timer = window.setInterval(() => { const left = Math.max(0, remaining - 1000); setRemaining(left); if (left === 0) resolveRound('timeout') }, 1000); return () => window.clearInterval(timer) }, [status, remaining])
  function beginRound(nextIndex: number, nextBudget: number) { roundStartedAt.current = Date.now(); const next = createVenueRound(difficulty, nextIndex); setIndex(nextIndex); setRound(next); setBuyId(next.venues[0].venueId); setSellId(next.venues[1].venueId); setQuantity('1'); setBudget(nextBudget); setTrade(null); setAction(null); setError(''); resolved.current = false; setRemaining(VENUE_GAP_SECONDS * 1000); setStatus('playing') }
  function start() { performanceDraft.current = beginSession('venue-gap', { rounds: VENUE_GAP_ROUNDS, startingBudget: VENUE_GAP_STARTING_BUDGET }, { difficulty, plannedItemCount: VENUE_GAP_ROUNDS }); setRecords([]); beginRound(0, VENUE_GAP_STARTING_BUDGET) }
  function resolveRound(nextAction: VenueGapAction) { if (resolved.current || status !== 'playing' || !round) return; resolved.current = true; const result = resolveVenueAction(nextAction, { budget }, buy, sell, Number(quantity)); const nextBudget = result.player.budget; setBudget(nextBudget); setTrade(result.trade); setAction(nextAction); const record: VenueRoundRecord = { action: nextAction, round, trade: result.trade, bestOpportunity: findBestOpportunity(round.venues), budgetBefore: budget, budget: nextBudget, opportunity: round.hasOpportunity, responseTimeMs: Math.max(0, Date.now() - roundStartedAt.current) }; const updated = [...records, record]; setRecords(updated); setStatus('reveal'); if (index < VENUE_GAP_ROUNDS - 1) advanceTimer.current = window.setTimeout(() => beginRound(index + 1, nextBudget), 1100); else advanceTimer.current = window.setTimeout(() => { const isCorrect = (item: VenueRoundRecord) => item.opportunity ? Boolean(item.trade && item.trade.netProfit > 0) : item.action !== 'arbitrage'; const correctCount = updated.filter(isCorrect).length; void persist(performanceDraft.current, updated.map(item => ({ payload: item, responseTimeMs: item.responseTimeMs, status: item.action === 'timeout' ? 'timed-out' : item.action === 'skip' ? 'skipped' : 'answered', outcome: isCorrect(item) ? 'correct' : 'incorrect' })), { terminationReason: 'rounds-completed', summary: { primaryScore: nextBudget - VENUE_GAP_STARTING_BUDGET, finalBudget: nextBudget, pnl: nextBudget - VENUE_GAP_STARTING_BUDGET, accuracy: correctCount / updated.length * 100, correctCount, answeredCount: updated.length, medianResponseTimeMs: median(updated.map(item => item.responseTimeMs)) } }, () => setStatus('results')) }, 1100) }
  function submit() { if (!buy || !sell || buy.venueId === sell.venueId) { setError('Choose two different venues.'); return } const amount = Number(quantity); if (!Number.isInteger(amount) || amount < 1 || amount > maxTradeQuantity(budget, buy, sell)) { setError(`Quantity must be an integer from 1 to ${maxTradeQuantity(budget, buy, sell)}.`); return } setError(''); resolveRound('arbitrage') }
  if (status === 'setup') return <VenueGapSetup difficulty={difficulty} onDifficulty={setDifficulty} onStart={start} />
  if (status === 'results') return <VenueGapResults records={records} budget={budget} onAgain={() => setStatus('setup')} onBack={() => navigate('/market-games')} />
  const feedback = status === 'reveal'; return <section className="page venue-gap-session"><div className="venue-gap-top"><div><p className="eyebrow">VENUE GAP / {difficulty.toUpperCase()}</p><p className="venue-gap-progress">Round <strong>{index + 1}/{VENUE_GAP_ROUNDS}</strong> · {round?.asset}</p></div><div><span className="venue-gap-budget">Budget {budget.toFixed(2)}</span><span className="timer" role="timer">{Math.ceil(remaining / 1000)}s</span></div></div><div className="venue-gap-board"><p className="venue-gap-asset">{round?.asset} / simultaneous quotes</p><table className="venue-gap-table"><thead><tr><th>Venue</th><th>Bid</th><th>Ask</th><th>Bid qty</th><th>Ask qty</th><th>Fee</th></tr></thead><tbody>{venues.map(venue => <tr key={venue.venueId}><td>{venue.name}</td><td><b>{venue.bid}</b></td><td><b>{venue.ask}</b></td><td>{venue.bidQuantity}</td><td>{venue.askQuantity}</td><td className="venue-gap-fee">{(venue.feeRate * 100).toFixed(2)}%</td></tr>)}</tbody></table>{feedback && <div className="venue-gap-feedback">{action === 'arbitrage' && trade ? `Buy ${trade.quantity} @ ${trade.buyPrice}, sell @ ${trade.sellPrice} · fees ${(trade.buyFee + trade.sellFee).toFixed(2)} · P/L ${trade.netProfit.toFixed(2)} · budget ${budget.toFixed(2)}` : action === 'timeout' ? 'Time expired: round skipped.' : best ? 'Opportunity missed.' : 'No profitable opportunity.'}</div>}</div>{!feedback && <div className="venue-gap-controls"><label>Buy on<select value={buyId} onChange={event => setBuyId(event.target.value)}>{venues.map(venue => <option key={venue.venueId} value={venue.venueId}>{venue.name} · ask {venue.ask}</option>)}</select></label><label>Sell on<select value={sellId} onChange={event => setSellId(event.target.value)}>{venues.map(venue => <option key={venue.venueId} value={venue.venueId}>{venue.name} · bid {venue.bid}</option>)}</select></label><label>Quantity<input inputMode="numeric" value={quantity} onChange={event => setQuantity(event.target.value.replace(/\D/g, ''))} min="1" /></label><button onClick={submit}>Execute arbitrage</button><button className="skip" onClick={() => resolveRound('skip')}>Skip round</button></div>}{error && <p className="input-error" role="alert">{error}</p>}</section>
}

type DeltaInstrument = { id: string; name: string; price: number; exposure: number; maxQuantity: number }
type DeltaRecord = { action: DeltaShieldAction; round: DeltaShieldRound; selected: DeltaInstrument | null; side: HedgeSide; quantity: number; initial: number; residual: number; cost: number; score: number; exposureReductionScore: number; optimal: DeltaInstrument | null; optimalQuantity: number; budgetBefore: number; budget: number; responseTimeMs: number }
function deltaInstruments(difficulty: DeltaShieldDifficulty): DeltaInstrument[] { const count = difficulty === 'Easy' ? 3 : difficulty === 'Medium' ? 4 : 5; return Array.from({ length: count }, (_, index) => ({ id: `hedge-${index + 1}`, name: `Hedge ${String.fromCharCode(65 + index)}`, price: 20 + index * 15, exposure: index % 2 ? -(index + 1) : index + 1, maxQuantity: difficulty === 'Hard' ? 12 - index : 20 })) }
function DeltaShieldSetup({ difficulty, onDifficulty, onStart }: { difficulty: DeltaShieldDifficulty; onDifficulty: (value: DeltaShieldDifficulty) => void; onStart: () => void }) { return <section className="page setup-page"><p className="eyebrow">MARKET GAMES / DELTA SHIELD</p><div className="game-heading"><span className="large-game-icon">⌁</span><div><h1>Delta Shield</h1><p className="section-intro">Reduce portfolio exposure after a market shock with one efficient hedge.</p></div></div><div className="setting hidden-difficulty"><label htmlFor="delta-shield-difficulty">Difficulty</label><select id="delta-shield-difficulty" value={difficulty} onChange={event => onDifficulty(event.target.value as DeltaShieldDifficulty)}><option>Easy</option><option>Medium</option><option>Hard</option></select></div><p className="hidden-rules">5 rounds · 60 seconds per round · 10,000 starting budget · one trade</p><button className="start-button" onClick={onStart}>Start market <span>→</span></button></section> }
function DeltaShieldResults({ records, budget, onAgain, onBack }: { records: DeltaRecord[]; budget: number; onAgain: () => void; onBack: () => void }) { const score = records.length ? records.reduce((sum, record) => sum + record.score, 0) / records.length : 0; const correct = records.filter(record => record.initial === 0 ? record.action !== 'hedge' : record.score >= 70).length; const missed = records.filter(record => record.initial !== 0 && record.action !== 'hedge').length; const suboptimal = records.filter(record => record.action === 'hedge' && record.score < 70).length; const cost = records.reduce((sum, record) => sum + record.cost, 0); return <section className="page hidden-results"><p className="eyebrow">DELTA SHIELD / COMPLETE</p><h1>Risk review.</h1><div className="delta-shield-metrics"><div><span>Average score</span><strong>{score.toFixed(1)}</strong></div><div><span>Final budget</span><strong>{budget.toFixed(2)}</strong></div><div><span>Coverage cost</span><strong>{cost.toFixed(2)}</strong></div><div><span>Correct rounds</span><strong>{correct}/{records.length}</strong></div><div><span>Missed / suboptimal</span><strong>{missed} / {suboptimal}</strong></div></div><div className="delta-shield-summary">{records.map((record, index) => <div key={index}><strong>Round {index + 1} · {record.action === 'hedge' ? 'Hedge' : record.action === 'timeout' ? 'Timeout' : 'Skip'}</strong><span>Exposure {record.initial} → {record.residual} · cost {record.cost.toFixed(2)} · score {record.score.toFixed(1)} · optimal {record.optimal ? `${record.optimal.name} ×${record.optimalQuantity}` : 'skip'}</span></div>)}</div><div className="actions"><button onClick={onAgain}>Play again</button><button className="secondary" onClick={onBack}>Back to market games</button></div></section> }
function DeltaShield() {
  const [difficulty, setDifficulty] = useState<DeltaShieldDifficulty>('Easy'); const [status, setStatus] = useState<'setup' | 'playing' | 'reveal' | 'results'>('setup'); const [index, setIndex] = useState(0); const [round, setRound] = useState<DeltaShieldRound | null>(null); const [instruments, setInstruments] = useState<DeltaInstrument[]>([]); const [instrumentId, setInstrumentId] = useState(''); const [side, setSide] = useState<HedgeSide>('buy'); const [quantity, setQuantity] = useState('1'); const [budget, setBudget] = useState(10000); const [remaining, setRemaining] = useState(0); const [records, setRecords] = useState<DeltaRecord[]>([]); const [error, setError] = useState(''); const [result, setResult] = useState<{ residual: number; cost: number; score: number; optimal: DeltaInstrument | null; optimalQuantity: number } | null>(null); const resolved = useRef(false); const advanceTimer = useRef<number | null>(null); const performanceDraft = useRef<SessionDraft | null>(null); const roundStartedAt = useRef(0); const navigate = useNavigate(); const selected = instruments.find(item => item.id === instrumentId) ?? null; const initial = round?.initialExposure ?? 0
  useEffect(() => () => { if (advanceTimer.current) window.clearTimeout(advanceTimer.current) }, [])
  useEffect(() => { if (status !== 'playing') return; const timer = window.setInterval(() => { const left = Math.max(0, remaining - 1000); setRemaining(left); if (left === 0) resolveRound('timeout') }, 1000); return () => window.clearInterval(timer) }, [status, remaining])
  function begin(nextIndex: number, nextBudget: number) { roundStartedAt.current = Date.now(); const next = generateDeltaRound(difficulty, nextIndex); const options = deltaInstruments(difficulty); setIndex(nextIndex); setRound(next); setInstruments(options); setInstrumentId(options[0].id); setSide('buy'); setQuantity('1'); setBudget(nextBudget); setResult(null); setError(''); resolved.current = false; setRemaining(DELTA_SHIELD_SECONDS * 1000); setStatus('playing') }
  function start() { performanceDraft.current = beginSession('delta-shield', { rounds: DELTA_SHIELD_ROUNDS, startingBudget: 10000 }, { difficulty, plannedItemCount: DELTA_SHIELD_ROUNDS }); setRecords([]); begin(0, 10000) }
  function bestSolution(): { instrument: DeltaInstrument | null; quantity: number; residual: number; cost: number } { let best = { instrument: null as DeltaInstrument | null, quantity: 0, residual: initial, cost: 0 }; for (const instrument of instruments) for (const direction of [1, -1]) for (let amount = 1; amount <= Math.min(instrument.maxQuantity, Math.floor(budget / instrument.price)); amount += 1) { const residual = applyHedgeTrade(initial, direction * amount, instrument.exposure); const cost = instrument.price * amount; if (Math.abs(residual) < Math.abs(best.residual) || Math.abs(residual) === Math.abs(best.residual) && cost < best.cost) best = { instrument, quantity: direction * amount, residual, cost } } return best }
  function resolveRound(nextAction: DeltaShieldAction) { if (resolved.current || status !== 'playing' || !round) return; resolved.current = true; const amount = Number(quantity); const signed = side === 'buy' ? amount : -amount; const valid = nextAction === 'hedge' && selected && Number.isInteger(amount) && amount > 0 && amount <= selected.maxQuantity && amount * selected.price <= budget; const best = bestSolution(); const residual = valid && selected ? applyHedgeTrade(initial, signed, selected.exposure) : initial; const cost = valid && selected ? selected.price * amount : 0; const score = valid ? Math.max(0, Math.min(100, 100 * (1 - Math.abs(residual) / Math.max(Math.abs(initial), 1)) * (1 - cost / 10000))) : 0; const nextBudget = budget - cost; setBudget(nextBudget); setResult({ residual, cost, score, optimal: best.instrument, optimalQuantity: best.quantity }); const exposureReductionScore = valid ? Math.max(0, Math.min(100, 100 * (1 - Math.abs(residual) / Math.max(Math.abs(initial), 1)))) : 0; const record: DeltaRecord = { action: nextAction, round, selected: valid ? selected : null, side, quantity: valid ? amount : 0, initial, residual, cost, score, exposureReductionScore, optimal: best.instrument, optimalQuantity: best.quantity, budgetBefore: budget, budget: nextBudget, responseTimeMs: Math.max(0, Date.now() - roundStartedAt.current) }; const updated = [...records, record]; setRecords(updated); setStatus('reveal'); if (index < DELTA_SHIELD_ROUNDS - 1) advanceTimer.current = window.setTimeout(() => begin(index + 1, nextBudget), 1100); else advanceTimer.current = window.setTimeout(() => { const average = updated.reduce((sum, item) => sum + item.score, 0) / updated.length; void persist(performanceDraft.current, updated.map(item => ({ payload: item, responseTimeMs: item.responseTimeMs, status: item.action === 'timeout' ? 'timed-out' : item.action === 'skip' ? 'skipped' : 'answered', outcome: Math.abs(item.residual) < Math.abs(item.initial) ? 'correct' : 'incorrect' })), { terminationReason: 'rounds-completed', summary: { primaryScore: average, averageScore: average, totalCost: updated.reduce((sum, item) => sum + item.cost, 0), finalBudget: nextBudget, medianResponseTimeMs: median(updated.map(item => item.responseTimeMs)) }, score: average }, () => setStatus('results')) }, 1100) }
  function submit() { if (!selected) { setError('Choose a hedge instrument.'); return } const amount = Number(quantity); if (!Number.isInteger(amount) || amount < 1 || amount > selected.maxQuantity || amount * selected.price > budget) { setError(`Quantity must be an integer from 1 to ${Math.min(selected.maxQuantity, Math.floor(budget / selected.price))}.`); return } setError(''); resolveRound('hedge') }
  if (status === 'setup') return <DeltaShieldSetup difficulty={difficulty} onDifficulty={setDifficulty} onStart={start} />
  if (status === 'results') return <DeltaShieldResults records={records} budget={budget} onAgain={() => setStatus('setup')} onBack={() => navigate('/market-games')} />
  const feedback = status === 'reveal'; return <section className="page delta-shield-session"><div className="delta-shield-top"><div><p className="eyebrow">DELTA SHIELD / {difficulty.toUpperCase()}</p><p className="delta-shield-progress">Round <strong>{index + 1}/{DELTA_SHIELD_ROUNDS}</strong></p></div><div><span className="delta-shield-budget">Budget {budget.toFixed(2)}</span><span className="timer" role="timer">{Math.ceil(remaining / 1000)}s</span></div></div><div className="delta-shield-board"><table className="delta-shield-table"><thead><tr><th>Position</th><th>Quantity</th><th>Exposure / unit</th><th>Total exposure</th></tr></thead><tbody>{round?.positions.map(position => <tr key={position.id}><td>{position.id.replace('position-', 'Position ')}</td><td>{position.quantity}</td><td>{position.shock}</td><td><b>{position.quantity * position.shock}</b></td></tr>)}</tbody></table><div className="delta-shield-shock"><span>Market shock factor</span><strong>×{round?.hedgeShock.toFixed(2)}</strong><span>Impact {initial * (round?.hedgeShock ?? 1)}</span></div><div className="delta-shield-exposure"><span>Current portfolio exposure</span><b>{feedback ? result?.residual : initial}</b></div>{feedback && result && <div className="delta-shield-feedback"><strong>Initial {result.residual - (side === 'buy' ? 1 : -1) * (selected?.exposure ?? 0) * Number(quantity)} · Residual {result.residual} · Cost {result.cost.toFixed(2)} · Score {result.score.toFixed(1)}</strong><br />Optimal: {result.optimal ? `${result.optimal.name}, ${result.optimalQuantity > 0 ? 'buy' : 'sell'} ×${Math.abs(result.optimalQuantity)} · residual ${applyHedgeTrade(initial, result.optimalQuantity, result.optimal.exposure)}` : 'Skip'}</div>}</div>{!feedback && <div className="delta-shield-hedge"><div className="delta-shield-side"><button type="button" className={side === 'buy' ? 'active' : ''} onClick={() => setSide('buy')}>Buy</button><button type="button" className={side === 'sell' ? 'active' : ''} onClick={() => setSide('sell')}>Sell</button></div><label>Instrument<select value={instrumentId} onChange={event => setInstrumentId(event.target.value)}>{instruments.map(instrument => <option key={instrument.id} value={instrument.id}>{instrument.name} · price {instrument.price} · exp {instrument.exposure}</option>)}</select></label><label>Quantity<input inputMode="numeric" value={quantity} onChange={event => setQuantity(event.target.value.replace(/\D/g, ''))} min="1" /></label><button onClick={submit}>Hedge</button><button className="skip" onClick={() => resolveRound(round?.balanced ? 'skip' : 'skip')}>Skip</button></div>}{error && <p className="input-error" role="alert">{error}</p>}</section>
}

function FormulaText({ text }: { text: string }) { const parts = text.split(/(\^\d+)/g); return <>{parts.map((part, index) => /^\^\d+$/.test(part) ? <sup className="formula-sup" key={index}>{part.slice(1)}</sup> : <span key={index}>{part}</span>)}</> }
function QuestionsSetup({ mode, difficulty, count, error, onMode, onDifficulty, onCount, onStart }: { mode: QuestionMode; difficulty: QuestionDifficulty | 'Mixed'; count: string; error: string; onMode: (value: QuestionMode) => void; onDifficulty: (value: QuestionDifficulty | 'Mixed') => void; onCount: (value: string) => void; onStart: () => void }) { const available = filterQuestions(mode, difficulty).length; return <section className="page questions-setup"><p className="eyebrow">QUESTIONS / INTERVIEW PRACTICE</p><h1>Questions</h1><p className="section-intro">Open-ended questions for quant, trader, and research interviews.</p><div className="questions-settings"><label>Mode<select value={mode} onChange={event => onMode(event.target.value as QuestionMode)}><option value="Mixed">Mixed</option>{QUESTION_CATEGORIES.map(category => <option key={category}>{category}</option>)}</select></label><label>Difficulty<select value={difficulty} onChange={event => onDifficulty(event.target.value as QuestionDifficulty | 'Mixed')}><option>Mixed</option><option>Easy</option><option>Medium</option><option>Hard</option></select></label><label>Questions<input type="number" min="1" value={count} onChange={event => onCount(event.target.value)} /></label></div><p className="questions-availability">{available} questions available in this filter · no timer</p>{error && <p className="input-error" role="alert">{error}</p>}<button className="start-button" onClick={onStart}>Start session <span>→</span></button></section> }
function QuestionsResults({ questions, mode, difficulty, onAgain }: { questions: InterviewQuestion[]; mode: QuestionMode; difficulty: QuestionDifficulty | 'Mixed'; onAgain: () => void }) { return <section className="page questions-results"><p className="eyebrow">QUESTIONS / COMPLETE</p><h1>Session complete.</h1><p className="section-intro">{questions.length} questions · {mode} · {difficulty}</p><div className="questions-results-list">{questions.map((question, index) => <div key={question.id}><strong>{index + 1}. {question.text}</strong><span>{question.category} · {question.difficulty}</span></div>)}</div><div className="actions"><button onClick={onAgain}>New session</button></div></section> }
function Questions() { const [mode, setMode] = useState<QuestionMode>('Mixed'); const [difficulty, setDifficulty] = useState<QuestionDifficulty | 'Mixed'>('Mixed'); const [count, setCount] = useState('10'); const [error, setError] = useState(''); const [status, setStatus] = useState<'setup' | 'playing' | 'results'>('setup'); const [session, setSession] = useState<InterviewQuestion[]>([]); const [index, setIndex] = useState(0); const [revealed, setRevealed] = useState(false); const current = session[index];
  function start() { const requested = Number(count); const available = filterQuestions(mode, difficulty).length; if (!Number.isInteger(requested) || requested < 1 || requested > available) { setError(`Enter an integer from 1 to ${available}.`); return } const selected = selectQuestions(mode, difficulty, requested); setSession(selected); setIndex(0); setRevealed(false); setError(''); setStatus('playing') }
  function next() { if (!revealed) return; if (index + 1 >= session.length) setStatus('results'); else { setIndex(index + 1); setRevealed(false) } }
  if (status === 'setup') return <QuestionsSetup mode={mode} difficulty={difficulty} count={count} error={error} onMode={value => { setMode(value); setError('') }} onDifficulty={value => { setDifficulty(value); setError('') }} onCount={setCount} onStart={start} />
  if (status === 'results') return <QuestionsResults questions={session} mode={mode} difficulty={difficulty} onAgain={() => setStatus('setup')} />
  return <section className="page questions-session"><div className="questions-session-top"><div><p className="eyebrow">QUESTIONS / {mode.toUpperCase()}</p><p className="progress">Question {index + 1} <span>/ {session.length}</span> · {current.category} · {current.difficulty}</p></div><span className="questions-counter">No timer</span></div><article className="questions-card" aria-live="polite"><p><FormulaText text={current.text} /></p>{revealed && <div className="questions-answer"><span>Answer</span><strong><FormulaText text={current.answer} /></strong></div>}</article><div className="questions-controls">{!revealed ? <button onClick={() => setRevealed(true)}>Show answer</button> : <button onClick={next}>{index + 1 === session.length ? 'Finish session' : 'Next question'} <span>→</span></button>}</div></section>
}

function GameSession({ name, difficulty, question, index, total, remaining, answer, feedback, inputRef, onAnswer, onSubmit, integer = false, questionClassName = 'question', questionHint, inputError, inputPlaceholder, sessionClassName = 'game-page' }: { name: string; difficulty: Difficulty; question: string; index: number; total: number; remaining: number; answer: string; feedback: FeedbackState | null; inputRef: RefObject<HTMLInputElement | null>; onAnswer: (value: string) => void; onSubmit: () => void; integer?: boolean; questionClassName?: string; questionHint?: string; inputError?: string; inputPlaceholder?: string; sessionClassName?: string }) {
  const describedBy = inputError ? `${name}-answer-error` : undefined
  return <section className={`page ${sessionClassName}`}><div className="game-top"><div><p className="eyebrow">{name.toUpperCase()} / {difficulty.toUpperCase()}</p><h1>Stay sharp.</h1></div><div className="timer" role="timer" aria-live="off" aria-label={`${Math.ceil(remaining / 1000)} seconds remaining`}>{Math.floor(remaining / 60_000)}:{String(Math.ceil(remaining / 1000) % 60).padStart(2, '0')}</div></div><div className="question-panel"><p className="progress">Question {index + 1} <span>/ {total}</span></p>{questionHint && <p className="precision-hint">{questionHint}</p>}{question && <div className={questionClassName} role="status" aria-live="polite" aria-atomic="true">{question}</div>}{feedback && <Feedback feedback={feedback} />}<form onSubmit={event => { event.preventDefault(); onSubmit() }}><label htmlFor={`${name}-answer`}>Your answer</label><div className={feedback ? `answer-row feedback-${feedback.correct ? 'correct' : 'incorrect'}` : 'answer-row'}><input ref={inputRef} id={`${name}-answer`} inputMode={integer ? 'numeric' : 'decimal'} pattern={integer ? '[+-]?\\d*' : undefined} aria-describedby={describedBy} aria-invalid={Boolean(inputError)} autoComplete="off" disabled={Boolean(feedback)} value={answer} onChange={event => onAnswer(event.target.value)} placeholder={inputPlaceholder ?? (integer ? 'Type an integer' : 'Type your answer')} /><button type="submit" disabled={Boolean(feedback)}>Submit <span>↵</span></button></div>{inputError && <small id={describedBy} className="input-error" role="alert">{inputError}</small>}</form></div></section>
}

export default function App() { return <Routes><Route element={<Layout />}><Route path="/" element={<Home />} /><Route path="/logic-and-math-games" element={<LogicGames />} /><Route path="/logic-and-math-games/quick-math" element={<QuickMath />} /><Route path="/logic-and-math-games/sequences" element={<Sequences />} /><Route path="/logic-and-math-games/radix-rush" element={<RadixRush />} /><Route path="/logic-and-math-games/tape-recall" element={<TapeRecall />} /><Route path="/logic-and-math-games/foldsight" element={<FoldSight />} /><Route path="/logic-and-math-games/magnitude-forge" element={<MagnitudeForge />} /><Route path="/market-games" element={<MarketGames />} /><Route path="/market-games/hidden-spread" element={<HiddenSpread />} /><Route path="/market-games/basket-edge" element={<BasketEdge />} /><Route path="/market-games/venue-gap" element={<VenueGap />} /><Route path="/market-games/delta-shield" element={<DeltaShield />} /><Route path="/open-questions" element={<Questions />} /><Route path="/statistics" element={<Statistics />} /><Route path="/statistics/:gameId" element={<Statistics />} /></Route></Routes> }
